           // 40FB10Pのフルスペック
           const currentSpecs = {'画面サイズ': '23 V型(インチ)', '画素数': '1366x768', 'パネル種類': 'None', 'HDR方式': 'None', '映像処理エンジン': 'None', 'バックライト': 'エッジ型LEDバックライト', '量子ドット': 'None', '倍速機能': 'None', 'BS 8K': 'None', 'BS 4K/110度CS 4K': 'None', '録画機能': '外付けHDD', 'ドライブ内蔵': 'None', '自動録画機能': 'None', '2番組同時録画': 'None', '早見再生': 'None', 'スマートスピーカー連携': 'None', '回転式スタンド': 'None', 'HDMI端子': '2端子MHL対応', 'リモコン(音声操作)': 'None', 'スピーカー数': 'None', '幅x高さx奥行': '545x388x163 mm', '重量': '3.6 kg'};



           // ====================================================================
